/* -------------------------------------------------------------------------- */
/*  Encryption helpers                                                        */
/* -------------------------------------------------------------------------- */
function generateKey() {
  return crypto.randomBytes(16);
}

function xorEncrypt(source, key) {
  const srcBuf = Buffer.from(source, 'utf8');
  const out = Buffer.alloc(srcBuf.length);
  for (let i = 0; i < srcBuf.length; i++) {
    out[i] = srcBuf[i] ^ key[i % key.length] ^ ((i * 31 + 17) & 0xff);
  }
  return out;
}

function bytesToLuaTable(buf) {
  const parts = [];
  for (let i = 0; i < buf.length; i++) parts.push(buf[i]);
  const lines = [];
  for (let i = 0; i < parts.length; i += 48) {
    lines.push(parts.slice(i, i + 48).join(','));
  }
  return '{' + lines.join(',') + '}';
}

function keyToLuaTable(key) {
  return '{' + Array.from(key).join(',') + '}';
}

function randomBytes(len) {
  return crypto.randomBytes(len);
}

function randomVar() {
  const chars = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
  let s = chars[Math.floor(Math.random() * 52)];
  for (let i = 0; i < 4 + Math.floor(Math.random() * 5); i++) {
    s += chars[Math.floor(Math.random() * 52)] + (Math.random() < 0.3 ? Math.floor(Math.random() * 10) : '');
  }
  return s;
}

function randomJunkString(len = 24) {
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  let s = '';
  for (let i = 0; i < len; i++) s += alphabet[Math.floor(Math.random() * alphabet.length)];
  return s;
}

function buildProtectedScript(luaSource) {
  const key = generateKey();
  const encrypted = xorEncrypt(luaSource, key);
  const realPayload = bytesToLuaTable(encrypted);
  const keyTable = keyToLuaTable(key);

  const decoyCount = 6 + Math.floor(Math.random() * 4);
  const realIndex = Math.floor(decoyCount / 2);

  const tables = [];
  const varNames = [];

  for (let i = 0; i < decoyCount; i++) {
    const v = randomVar();
    varNames.push(v);
    if (i === realIndex) {
      tables.push(`local ${v}=${realPayload}`);
    } else {
      const fakeLen = 40 + Math.floor(Math.random() * 120);
      const fake = bytesToLuaTable(randomBytes(fakeLen));
      tables.push(`local ${v}=${fake}`);
    }
  }

  const junkVars = [];
  for (let i = 0; i < 5; i++) {
    const v = randomVar();
    junkVars.push(`local ${v}="${randomJunkString(16 + Math.floor(Math.random() * 40))}"`);
  }

  const middleBlock = [
    junkVars[0],
    junkVars[1],
    ...tables.slice(0, realIndex),
    tables[realIndex],
    ...tables.slice(realIndex + 1),
    junkVars[2],
    junkVars[3],
    junkVars[4],
  ].join(';');

  const realVar = varNames[realIndex];
  const keyVar = randomVar();
  const srcVar = randomVar();
  const fnVar = randomVar();

  const loader = `local ${keyVar}=${keyTable};${middleBlock};local ${srcVar}={};for i=1,#${realVar} do local b=${realVar}[i];local kb=${keyVar}[((i-1)%#${keyVar})+1];${srcVar}[i]=string.char(bit32.bxor(b,kb,bit32.band(i*31+17,255)))end;local ${fnVar},err=loadstring(table.concat(${srcVar}));if not ${fnVar} then error(err or"HyperionV1 load failed",0)end;${fnVar}()`;

  return `do ${ANTITAMPER_BODY};${loader} end\n`;
}

// --- LUA MINIFIER & OBFUSCATOR ENGINE ---
function minifyLua(code) {
    code = code.replace(/--\[\[[\s\S]*?\]\]/g, '');
    code = code.replace(/--[^\r\n]*/g, '');
    const lines = code.split(/\r?\n/);
    const cleaned = lines.map(l => l.trim()).filter(l => l.length > 0);
    return cleaned.join('\n');
}

function compactOutput(output) {
    // Preserve a leading single-line comment watermark if present, then compact the rest
    let watermark = '';
    const wmMatch = output.match(/^--[^\r\n]*(?:\r?\n)?/);
    if (wmMatch) {
        watermark = wmMatch[0].replace(/\r?\n$/, '') + '\n';
        output = output.slice(wmMatch[0].length);
    }

    const compacted = output
        .split(/\r?\n/)
        .map(line => line.trim())
        .filter(Boolean)
        .join(';')
        .replace(/;{2,}/g, ';')
        .replace(/^;+|;+$/g, '');

    return watermark + compacted;
}

function obfuscateLua(code) {
    return buildProtectedScript(code);
}

function buildPortableEncryptedScript(code) {
    const key = Math.floor(Math.random() * 200) + 20;
    const bytes = [...Buffer.from(code, 'utf8')].map(byte => (byte + key) % 256).join(',');
    const rand = () => '_' + Math.random().toString(36).slice(2, 10);
    const dataName = rand(), keyName = rand(), sourceName = rand(), loaderName = rand();
    return `local ${dataName}={${bytes}};local ${keyName}=${key};local ${sourceName}={};for i=1,#${dataName} do ${sourceName}[i]=string.char((${dataName}[i]-${keyName})%256) end;local ${loaderName}=loadstring or load;if not ${loaderName} then error("This Lua environment does not support loading source",0) end;local f,e=${loaderName}(table.concat(${sourceName}));if not f then error(e or "Unable to load obfuscated source",0) end;return f()`;
}

// Extra junk / string-dump helpers for higher levels
function generateJunkLines(count = 8) {
    const lines = [];
    for (let i = 0; i < count; i++) {
        const v = randomVar();
        if (Math.random() < 0.5) {
            lines.push(`local ${v}="${randomJunkString(20 + Math.floor(Math.random()*30))}"`);
        } else {
            const n = Math.floor(Math.random() * 99999);
            lines.push(`local ${v}=${n}`);
        }
    }
    return lines.join(';');
}

function stringDumpWrap(code) {
    // Simple string dump style wrapper for Level 2/3
    const key = Math.floor(Math.random() * 180) + 40;
    const encoded = [...Buffer.from(code, 'utf8')].map(b => (b + key) % 256);
    const dataVar = randomVar();
    const keyVar = randomVar();
    const outVar = randomVar();
    const fnVar = randomVar();
    return `local ${dataVar}={${encoded.join(',')}};local ${keyVar}=${key};local ${outVar}={};for i=1,#${dataVar} do ${outVar}[i]=string.char((${dataVar}[i]-${keyVar})%256)end;local ${fnVar}=loadstring or load;local f,e=${fnVar}(table.concat(${outVar}));if not f then error(e or"load fail",0)end;f()`;
}

function applyPremiumObfuscation(source, level, provider) {
    let protected = minifyLua(source);

    // Level based strength
    if (level === 1) {
        protected = buildPortableEncryptedScript(protected);
    } else if (level === 2) {
        // Extra junk + string dump
        const junk = generateJunkLines(10);
        protected = stringDumpWrap(protected);
        protected = `${junk};${protected}`;
        protected = buildProtectedScript(protected);
    } else { // level 3
        // Heavier: multi-layer + more junk + string dump
        const junk1 = generateJunkLines(14);
        const junk2 = generateJunkLines(10);
        protected = stringDumpWrap(protected);
        protected = `${junk1};${protected}`;
        protected = buildProtectedScript(protected);
        protected = `${junk2};${protected}`;
        protected = buildProtectedScript(protected); // second layer
    }

    // Choose anti-tamper
    let anti = '';
    if (provider === 'xhider') anti = XHIDER_ANTITAMPER;
    else if (provider === 'aqua') anti = AQUA_ANTITAMPER;
    else if (provider === 'firefly') anti = FIREFLY_ANTITAMPER;

    // Combine: anti-tamper first, then the protected payload
    let final = anti ? `${anti}\n${protected}` : protected;

    // Always compact
    return compactOutput(final);
}

