function applyWatermark(output, settings) {
    // Remove any existing Hyperion / old watermark so we don't stack them
    output = output.replace(/^--[^\r\n]*(?:HyperionV1|This File Was Protected)[^\r\n]*\r?\n?/, '');

    let watermark = '';
    if (settings.watermark === 'hyperion') {
        watermark = HYPERION_WATERMARK;
    } else if (settings.watermark === 'custom') {
        let text = (settings.watermarkText || '').trim();
        // Always force it into a Lua comment
        text = text.replace(/^--+ */, '');   // strip any existing -- the user typed
        if (text) watermark = `--${text}`;
    }

    return watermark ? `${watermark}\n${output}` : output;
}

